  1	/**
  2	 * Settings View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders four settings sections:
  5	 *   1. **Git Credentials** — table of per-host PATs with add/delete controls.
  6	 *   2. **Repositories Refresh Delay** — number input for `gitPollingIntervalSeconds`
  7	 *      with client-side validation (min 10) and save/feedback.
  8	 *   3. **Webserver URL** — text input for the base URL of the local webserver
  9	 *      that serves the workspace repositories, enabling the "Browse" button in
 10	 *      the workspace-detail view.
 11	 *   4. **Notes Display** — number inputs for card height (px) and column count
 12	 *      with client-side range validation and save/feedback.
 13	 *
 14	 * This view has no side-effects (no polling), so it returns no cleanup function.
 15	 *
 16	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 17	 * @param {Object}      _params   - Route params (none for this route).
 18	 */
 19	
 20	import { api } from '../api.js';
 21	import { showToast } from '../components/toast.js';
 22	import { showConfirm } from '../components/confirm-dialog.js';
 23	import { APP_NAME_SHORT } from '../utils/constants.js';
 24	import { createFormField, validateRequired } from '../components/form-helpers.js';
 25	import { clearElement } from '../utils/dom.js';
 26	
 27	// ---------------------------------------------------------------------------
 28	// Table rendering
 29	// ---------------------------------------------------------------------------
 30	
 31	/**
 32	 * Build the `<thead>` for the credentials table.
 33	 *
 34	 * @returns {HTMLElement}
 35	 */
 36	function buildTableHead() {
 37	    const thead = document.createElement('thead');
 38	    const tr = document.createElement('tr');
 39	
 40	    ['Host', 'Token', 'Actions'].forEach((label) => {
 41	        const th = document.createElement('th');
 42	        th.textContent = label;
 43	        tr.appendChild(th);
 44	    });
 45	
 46	    thead.appendChild(tr);
 47	    return thead;
 48	}
 49	
 50	/**
 51	 * Build a single `<tr>` for one credential entry.
 52	 *
 53	 * @param {string}            host       - The hostname key.
 54	 * @param {string}            maskedToken - The masked token string (e.g. `****abc1`).
 55	 * @param {function(): void}  onDeleted  - Callback to refresh the table after deletion.
 56	 * @returns {HTMLTableRowElement}
 57	 */
 58	function buildCredentialRow(host, maskedToken, onDeleted) {
 59	    const tr = document.createElement('tr');
 60	    tr.dataset.credHost = host;
 61	
 62	    // ---- Host cell (read-only) ----
 63	    const hostCell = document.createElement('td');
 64	    hostCell.className = 'cred-host-cell';
 65	    hostCell.textContent = host;
 66	    tr.appendChild(hostCell);
 67	
 68	    // ---- Masked token cell (read-only) ----
 69	    const tokenCell = document.createElement('td');
 70	    tokenCell.className = 'cred-token-cell text-muted';
 71	    tokenCell.textContent = maskedToken;
 72	    tr.appendChild(tokenCell);
 73	
 74	    // ---- Actions cell ----
 75	    const actionsCell = document.createElement('td');
 76	    actionsCell.className = 'cred-actions-cell';
 77	
 78	    const deleteBtn = document.createElement('button');
 79	    deleteBtn.type = 'button';
 80	    deleteBtn.className = 'btn btn-danger btn-sm';
 81	    deleteBtn.textContent = 'Delete';
 82	
 83	    actionsCell.appendChild(deleteBtn);
 84	    tr.appendChild(actionsCell);
 85	
 86	    // ---- Behaviour ----
 87	
 88	    deleteBtn.addEventListener('click', async () => {
 89	        try {
 90	            await showConfirm(
 91	                'Delete Credential',
 92	                `Remove the credential for "${host}"? This action cannot be undone.`,
 93	            );
 94	        } catch {
 95	            // User cancelled — do nothing.
 96	            return;
 97	        }
 98	
 99	        deleteBtn.disabled = true;
100	        deleteBtn.textContent = 'Deleting…';

101	
102	        try {
103	            await api.config.credentials.delete(host);
104	            showToast(`Credential for "${host}" deleted.`, 'success');
105	            onDeleted();
106	        } catch (err) {
107	            showToast(err.message || 'Failed to delete credential.', 'error');
108	            deleteBtn.disabled = false;
109	            deleteBtn.textContent = 'Delete';
110	        }
111	    });
112	
113	    return tr;
114	}
115	
116	// ---------------------------------------------------------------------------
117	// Credentials table rendering
118	// ---------------------------------------------------------------------------
119	
120	/**
121	 * Render a loading indicator into `tableContainer`.
122	 *
123	 * @param {HTMLElement} tableContainer
124	 */
125	function showLoading(tableContainer) {
126	    tableContainer.innerHTML = `
127	        <div class="loading-indicator" aria-live="polite" aria-label="Loading credentials…">
128	            <span class="spinner" aria-hidden="true"></span>
129	            <span>Loading credentials…</span>
130	        </div>
131	    `;
132	}
133	
134	/**
135	 * Fetch all credentials and render them into `tableContainer`.
136	 *
137	 * @param {HTMLElement} tableContainer
138	 */
139	async function renderCredentialsTable(tableContainer) {
140	    showLoading(tableContainer);
141	
142	    let credentials;
143	    try {
144	        credentials = await api.config.credentials.list();
145	    } catch (err) {
146	        clearElement(tableContainer);
147	        const errorP = document.createElement('p');
148	        errorP.className = 'error-message';
149	        errorP.setAttribute('role', 'alert');
150	        errorP.textContent = `Failed to load credentials: ${err.message || 'Unknown error'}`;
151	        tableContainer.appendChild(errorP);
152	        return;
153	    }
154	
155	    const entries = Object.entries(credentials || {});
156	
157	    if (entries.length === 0) {
158	        tableContainer.innerHTML = `
159	            <p class="empty-state">No credentials configured. Use the form below to add one.</p>
160	        `;
161	        return;
162	    }
163	
164	    const table = document.createElement('table');
165	    table.className = 'credentials-table';
166	    table.setAttribute('role', 'table');
167	    table.setAttribute('aria-label', 'Git credentials');
168	
169	    table.appendChild(buildTableHead());
170	
171	    const tbody = document.createElement('tbody');
172	
173	    for (const [host, maskedToken] of entries) {
174	        tbody.appendChild(buildCredentialRow(host, maskedToken, () => {
175	            renderCredentialsTable(tableContainer);
176	        }));
177	    }
178	
179	    table.appendChild(tbody);
180	    clearElement(tableContainer);
181	    tableContainer.appendChild(table);
182	}
183	
184	// ---------------------------------------------------------------------------
185	// Add / Update credential form
186	// ---------------------------------------------------------------------------
187	
188	/**
189	 * Build the "Add / Update Credential" section with a toggle button and inline form.
190	 *
191	 * @param {HTMLElement} tableContainer - Used to trigger a refresh after a successful save.
192	 * @returns {HTMLElement} The wrapper element containing the toggle button and form.
193	 */
194	function buildAddCredentialForm(tableContainer) {
195	    const section = document.createElement('div');
196	    section.className = 'add-credential-section';
197	
198	    const toggleBtn = document.createElement('button');
199	    toggleBtn.type = 'button';
200	    toggleBtn.className = 'btn btn-primary';
201	    toggleBtn.textContent = 'Add / Update Credential';
202	
203	    const formWrapper = document.createElement('div');
204	    formWrapper.className = 'form-wrapper';
205	    formWrapper.hidden = true;
206	
207	    const form = document.createElement('form');
208	    form.noValidate = true;
209	
210	    form.appendChild(createFormField('Host', 'text', 'host', {
211	        placeholder: 'e.g. github.com',
212	        required: true,
213	    }));
214	
215	    form.appendChild(createFormField('Token', 'password', 'token', {
216	        placeholder: 'Personal access token',
217	        required: true,
218	    }));
219	
220	    const actions = document.createElement('div');
221	    actions.className = 'form-actions';
222	
223	    const submitBtn = document.createElement('button');
224	    submitBtn.type = 'submit';
225	    submitBtn.className = 'btn btn-primary';
226	    submitBtn.textContent = 'Save';
227	
228	    const cancelBtn = document.createElement('button');
229	    cancelBtn.type = 'button';
230	    cancelBtn.className = 'btn btn-secondary';
231	    cancelBtn.textContent = 'Cancel';
232	
233	    actions.appendChild(submitBtn);
234	    actions.appendChild(cancelBtn);
235	    form.appendChild(actions);
236	    formWrapper.appendChild(form);
237	
238	    section.appendChild(toggleBtn);
239	    section.appendChild(formWrapper);
240	
241	    // ---- Behaviour ----
242	
243	    toggleBtn.addEventListener('click', () => {
244	        formWrapper.hidden = !formWrapper.hidden;
245	        if (!formWrapper.hidden) {
246	            const hostInput = form.querySelector('[name="host"]');
247	            if (hostInput) hostInput.focus();
248	        }
249	    });
250	
251	    cancelBtn.addEventListener('click', () => {
252	        form.reset();
253	        formWrapper.hidden = true;
254	    });
255	
256	    form.addEventListener('submit', async (e) => {
257	        e.preventDefault();
258	
259	        if (!validateRequired(form, ['host', 'token'])) return;
260	
261	        const host  = form.querySelector('[name="host"]').value.trim();
262	        const token = form.querySelector('[name="token"]').value.trim();
263	
264	        submitBtn.disabled = true;
265	        submitBtn.textContent = 'Saving…';
266	
267	        try {
268	            await api.config.credentials.set({ host, token });
269	            showToast(`Credential for "${host}" saved.`, 'success');
270	            form.reset();
271	            formWrapper.hidden = true;
272	            renderCredentialsTable(tableContainer);
273	        } catch (err) {
274	            showToast(err.message || 'Failed to save credential.', 'error');
275	        } finally {
276	            submitBtn.disabled = false;
277	            submitBtn.textContent = 'Save';
278	        }
279	    });
280	
281	    return section;
282	}
283	
284	// ---------------------------------------------------------------------------
285	// Repositories Refresh Delay section
286	// ---------------------------------------------------------------------------
287	
288	/**
289	 * Build the "Repositories Refresh Delay" section.
290	 *
291	 * Fetches the current server-side `gitPollingIntervalSeconds` value on mount,
292	 * populates a number input, and exposes a `save()` function for the shared
293	 * settings footer button.
294	 *
295	 * @returns {{ element: HTMLElement, save: () => Promise<boolean> }}
296	 */
297	function buildRefreshDelaySection() {
298	    const section = document.createElement('section');
299	    section.className = 'settings-section refresh-delay-section';

301	    const heading = document.createElement('h2');
302	    heading.textContent = 'Repositories Refresh Delay';
303	    section.appendChild(heading);
304	
305	    const description = document.createElement('p');
306	    description.textContent =
307	        'How often (in seconds) the server polls remote repositories for new commits. ' +
308	        'Changes take effect immediately — the current polling cycle is restarted with the new interval. ' +
309	        'Minimum value is 10 seconds.';
310	    section.appendChild(description);
311	
312	    // ---- Input row ----
313	    const inputRow = document.createElement('div');
314	    inputRow.className = 'refresh-delay-input-row';
315	
316	    const label = document.createElement('label');
317	    label.htmlFor = 'refresh-delay-input';
318	    label.textContent = 'Interval';
319	    label.className = 'refresh-delay-label';
320	
321	    const input = document.createElement('input');
322	    input.type = 'number';
323	    input.id = 'refresh-delay-input';
324	    input.name = 'refreshDelay';
325	    input.className = 'form-input refresh-delay-input';
326	    input.min = '10';
327	    // Maximum matches server-side MAX_POLLING_INTERVAL_SECONDS in src/config/config.constants.ts
328	    input.max = '86400';
329	    input.step = '1';
330	    input.placeholder = '30';
331	    input.setAttribute('aria-label', 'Polling interval in seconds');
332	
333	    const unitLabel = document.createElement('span');
334	    unitLabel.className = 'refresh-delay-unit';
335	    unitLabel.textContent = 'seconds';
336	
337	    inputRow.appendChild(label);
338	    inputRow.appendChild(input);
339	    inputRow.appendChild(unitLabel);
340	    section.appendChild(inputRow);
341	
342	    // ---- Inline error message ----
343	    const errorMsg = document.createElement('p');
344	    errorMsg.className = 'error-message';
345	    errorMsg.setAttribute('role', 'alert');
346	    errorMsg.hidden = true;
347	    section.appendChild(errorMsg);
348	
349	    // ---- Populate current value on mount ----
350	    (async () => {
351	        try {
352	            const cfg = await api.config.polling.get();
353	            if (cfg && typeof cfg.gitPollingIntervalSeconds === 'number') {
354	                input.value = String(cfg.gitPollingIntervalSeconds);
355	            }
356	        } catch {
357	            // Non-fatal — leave the placeholder in place.
358	        }
359	    })();
360	
361	    // ---- Save function (called by the shared footer button) ----
362	    async function save() {
363	        const raw   = input.value.trim();
364	        const value = Number(raw);
365	
366	        if (!raw || !Number.isFinite(value) || !Number.isInteger(value) || value < 10) {
367	            errorMsg.textContent = 'Please enter a whole number of 10 or more.';
368	            errorMsg.hidden = false;
369	            input.focus();
370	            return false;
371	        }
372	
373	        if (value > 86400) {
374	            errorMsg.textContent = 'Please enter a value of 86400 or less (24 hours maximum).';
375	            errorMsg.hidden = false;
376	            input.focus();
377	            return false;
378	        }
379	
380	        errorMsg.hidden = true;
381	
382	        try {
383	            await api.config.polling.set(value);
384	            return true;
385	        } catch (err) {
386	            showToast(err.message || 'Failed to save refresh delay.', 'error');
387	            return false;
388	        }
389	    }
390	
391	    return { element: section, save };
392	}
393	
394	// ---------------------------------------------------------------------------
395	// Webserver URL section
396	// ---------------------------------------------------------------------------
397	
398	/**
399	 * Build the "Webserver URL" section.
400	 *
401	 * Fetches the current server-side `webserverUrl` value on mount, populates a
402	 * text input, and exposes a `save()` function for the shared settings footer
403	 * button.
404	 *
405	 * @returns {{ element: HTMLElement, save: () => Promise<boolean> }}
406	 */
407	function buildWebserverUrlSection() {
408	    const section = document.createElement('section');
409	    section.className = 'settings-section webserver-url-section';
410	
411	    const heading = document.createElement('h2');
412	    heading.textContent = 'Webserver URL';
413	    section.appendChild(heading);
414	
415	    const description = document.createElement('p');
416	    description.textContent =
417	        'Base URL of the local webserver serving your workspace repositories. ' +
418	        'When set, a "Browse" button appears in the workspace-detail view for each ' +
419	        'repository. The URL should point to the root of your projects folder ' +
420	        '(e.g. http://localhost:8080). Leave empty to hide the Browse button.';
421	    section.appendChild(description);
422	
423	    // ---- Input row ----
424	    const inputRow = document.createElement('div');
425	    inputRow.className = 'webserver-url-input-row';
426	
427	    const label = document.createElement('label');
428	    label.htmlFor = 'webserver-url-input';
429	    label.textContent = 'URL';
430	    label.className = 'webserver-url-label';
431	
432	    const input = document.createElement('input');
433	    input.type = 'url';
434	    input.id = 'webserver-url-input';
435	    input.name = 'webserverUrl';
436	    input.className = 'form-input webserver-url-input';
437	    input.placeholder = 'http://localhost:8080';
438	    input.setAttribute('aria-label', 'Webserver base URL');
439	
440	    inputRow.appendChild(label);
441	    inputRow.appendChild(input);
442	    section.appendChild(inputRow);
443	
444	    // ---- Inline error message ----
445	    const errorMsg = document.createElement('p');
446	    errorMsg.className = 'error-message';
447	    errorMsg.setAttribute('role', 'alert');
448	    errorMsg.hidden = true;
449	    section.appendChild(errorMsg);
450	
451	    // ---- Populate current value on mount ----
452	    (async () => {
453	        try {
454	            const cfg = await api.config.webserverUrl.get();
455	            if (cfg && typeof cfg.webserverUrl === 'string') {
456	                input.value = cfg.webserverUrl;
457	            }
458	        } catch {
459	            // Non-fatal — leave the placeholder in place.
460	        }
461	    })();
462	
463	    // ---- Save function (called by the shared footer button) ----
464	    async function save() {
465	        errorMsg.hidden = true;
466	
467	        try {
468	            await api.config.webserverUrl.set(input.value.trim());
469	            return true;
470	        } catch (err) {
471	            showToast(err.message || 'Failed to save webserver URL.', 'error');
472	            return false;
473	        }
474	    }
475	
476	    return { element: section, save };
477	}
478	
479	// ---------------------------------------------------------------------------
480	// Notes Display section
481	// ---------------------------------------------------------------------------
482	
483	/**
484	 * Build the "Notes Display" section.
485	 *
486	 * Fetches the current `notesCardHeight` and `notesColumns` values from
487	 * GET /api/config/notes-display on mount, populates number inputs, and
488	 * exposes a `save()` function for the shared settings footer button.
489	 *
490	 * Card height range : 120–800 px (step 10, default 220).
491	 * Columns range     : 1–6 (step 1, default 2).
492	 *
493	 * @returns {{ element: HTMLElement, save: () => Promise<boolean> }}
494	 */
495	function buildNotesDisplaySection() {
496	    const section = document.createElement('section');
497	    section.className = 'settings-section notes-display-section';
498	
499	    const heading = document.createElement('h2');
500	    heading.textContent = 'Notes Display';
501	    section.appendChild(heading);
502	
503	    const description = document.createElement('p');
504	    description.textContent =
505	        'Control how notes are presented in the Notes view. ' +
506	        'Card Height sets the pixel height of each note card; ' +
507	        'Columns sets how many cards appear side-by-side in the grid.';
508	    section.appendChild(description);
509	
510	    // ---- Card Height input row ----
511	    const cardHeightRow = document.createElement('div');
512	    cardHeightRow.className = 'notes-display-input-row';
513	
514	    const cardHeightLabel = document.createElement('label');
515	    cardHeightLabel.htmlFor = 'notes-card-height-input';
516	    cardHeightLabel.textContent = 'Card Height';
517	    cardHeightLabel.className = 'notes-display-label';
518	
519	    const cardHeightInput = document.createElement('input');
520	    cardHeightInput.type = 'number';
521	    cardHeightInput.id = 'notes-card-height-input';
522	    cardHeightInput.name = 'notesCardHeight';
523	    cardHeightInput.className = 'form-input notes-display-input';
524	    cardHeightInput.min = '120';
525	    cardHeightInput.max = '800';
526	    cardHeightInput.step = '10';
527	    cardHeightInput.placeholder = '220';
528	    cardHeightInput.setAttribute('aria-label', 'Note card height in pixels');
529	
530	    const cardHeightUnit = document.createElement('span');
531	    cardHeightUnit.className = 'notes-display-unit';
532	    cardHeightUnit.textContent = 'px';
533	
534	    cardHeightRow.appendChild(cardHeightLabel);
535	    cardHeightRow.appendChild(cardHeightInput);
536	    cardHeightRow.appendChild(cardHeightUnit);
